CREATE TABLE IF NOT EXISTS `info_code_config` (
    `id` varchar(200) NOT NULL COMMENT '主键ID，业务生成',
    `group_code` varchar(64) DEFAULT NULL COMMENT '集团编码',
    `project_id` varchar(50) DEFAULT NULL COMMENT '项目id',
    `info_code` varchar(200) DEFAULT NULL COMMENT '信息点编码',
    `name` varchar(200) DEFAULT NULL COMMENT '信息点名称',
    `alias_name` varchar(200) DEFAULT NULL COMMENT '信息点别名',
    `abbreviation_name` varchar(200) DEFAULT NULL COMMENT '缩略名',
    `class_code` varchar(200) DEFAULT NULL COMMENT '对象类编码',
    `class_name` varchar(200) DEFAULT NULL COMMENT '对象类名称',
    `merge_code` varchar(200) DEFAULT NULL COMMENT '聚合编码',
    `merge_name` varchar(200) DEFAULT NULL COMMENT '聚合名称',
    `group_info` varchar(64) DEFAULT NULL COMMENT '分组信息',
    `unit` varchar(50) DEFAULT NULL COMMENT '单位',
    `scale` varchar(20) DEFAULT NULL COMMENT '换算系数',
    `obj_type` varchar(100) DEFAULT NULL COMMENT '对象类型',
    `data_type` varchar(100) DEFAULT NULL COMMENT '数据类型',
    `first_tag` varchar(200) DEFAULT NULL COMMENT '一级标签',
    `second_tag` varchar(200) DEFAULT NULL COMMENT '二级标签',
    `ordered` varchar(20) DEFAULT NULL COMMENT '显示顺序',
    `data_source` json DEFAULT NULL COMMENT '枚举类型信息点的数据源',
    `extend_info` json DEFAULT NULL COMMENT '扩展字段',
    `create_time` datetime DEFAULT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_time` datetime DEFAULT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (`id`) USING BTREE,
    KEY `nk_info_code_config_class_code` (`class_code`) USING BTREE COMMENT '设备类级别索引',
    KEY `nk_info_code_config_info_code` (`info_code`) USING BTREE COMMENT '信息点索引'
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 ROW_FORMAT = DYNAMIC COMMENT = '信息点配置详情';

DELETE FROM info_code_config;
